#include <iostream>
#include <algorithm>
using namespace std;
int main(){int n;if(!(cin>>n))return 0;long long x;cin>>x;long long m=x,c=x;for(int i=1;i<n;i++){cin>>x;c=max(x,c+x);m=max(m,c);}cout<<m<<"\n";return 0;}

